"""唯讀列出 llmcall、author 與 budget 尚未完成的紀錄。"""
import argparse
import json
from pathlib import Path
import re


def load(path):
    try:
        return json.loads(path.read_text(encoding='utf-8'))
    except (OSError, ValueError):
        return None


def diagnose(node):
    pending, halted, inflight = [], [], []
    for path in sorted(node.glob('llmcall/*/*/request.json')):
        if isinstance(load(path), dict) and not (path.parent / 'receipt.json').exists():
            raw = path.parent / 'raw.json'
            pending.append(dict(budget=path.parent.parent.name, call_id=path.parent.name, stage='raw' if raw.exists() else 'request'))
    for path in sorted(node.glob('jobs/*/frame.json')):
        frame = load(path)
        job = path.parent.name
        m = re.fullmatch(r'(.+)_[0-9a-fA-F]{8}', job)
        if isinstance(frame, dict) and frame.get('phase') == 'halted' and m and (node / 'author/req' / m[1]).is_dir():
            halt = frame.get('halt', {})
            halted.append(dict(job=job, rid=m[1], kind=halt.get('kind'), why=halt.get('why')))
    for path in sorted(node.glob('budget/*/ledger.json')):
        ledger = load(path)
        if isinstance(ledger, dict) and type(ledger.get('inflight')) is int and ledger['inflight'] > 0:
            inflight.append(dict(budget=path.parent.name, inflight=ledger['inflight']))
    return dict(v=1, llmcall_pending=pending, author_halted=halted, budget_inflight=inflight)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('node', type=Path)
    a = ap.parse_args()
    if not a.node.is_dir():
        return 2
    print(json.dumps(diagnose(a.node), ensure_ascii=False))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
